"use strict";(globalThis.webpackChunkllm_d_website=globalThis.webpackChunkllm_d_website||[]).push([[7681],{48045(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>o,toc:()=>h});var o=n(27571),i=n(74848),a=n(28453);const s={title:"Serving Hybrid Models at Scale in llm-d",description:"llm-d extends vLLM's Hybrid Memory Allocator across KV offloading to CPU and storage and KV-aware routing, making the offload connector HMA-aware - for 1.8\u20131.9x faster KV loads and about 115% higher throughput at high request rates with stable latency.",slug:"serving-hybrid-models-at-scale-in-llm-d",date:"2026-06-13T09:00",authors:["kfirtoledo","orozeri","dannyharnik","itayetelis","rachelbrill","maroonayoub-redhat"],tags:["blog","kv-cache","storage","hma","inference","scheduling"]},r="Serving Hybrid Models at Scale in llm-d",l={authorsImageUrls:[void 0,void 0,void 0,void 0,void 0,void 0]},h=[{value:"KV Cache Offloading for Hybrid Models",id:"kv-cache-offloading-for-hybrid-models",level:2},{value:"Handling KV Data for Hybrid Models",id:"handling-kv-data-for-hybrid-models",level:3},{value:"Handling Hybrid KV by an Offloading Connector",id:"handling-hybrid-kv-by-an-offloading-connector",level:3},{value:"Performance Benefits: Nearly Double the Load Speed",id:"performance-benefits-nearly-double-the-load-speed",level:2},{value:"Scaling Benefits of HMA-Aware Offloading",id:"scaling-benefits-of-hma-aware-offloading",level:2},{value:"KV-Aware Request Routing",id:"kv-aware-request-routing",level:2},{value:"What&#39;s Next",id:"whats-next",level:2},{value:"Get Involved with llm-d",id:"get-involved-with-llm-d",level:2}];function d(e){const t={a:"a",h2:"h2",h3:"h3",li:"li",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(t.p,{children:["For most of the transformer era, the KV cache rested on a quiet assumption: ",(0,i.jsx)(t.strong,{children:"one model, one uniform cache"}),". Every layer attended the same way, every block was the same size, and everything built on top of the cache (allocators, offload connectors, schedulers) could treat it as a single pool."]}),"\n",(0,i.jsx)(t.p,{children:"Hybrid models broke this assumption. Many recent frontier and open-weight models increasingly mix attention types within a single model (full attention next to sliding-window, linear, or Mamba layers), making the cache heterogeneous: different layers now hold different amounts of state, in different shapes, with different reuse rules. A cache block that used to be allocated as one uniform unit is now constituted of several distinct parts."}),"\n",(0,i.jsxs)(t.p,{children:["To serve a hybrid model efficiently, an AI inference platform has to handle that heterogeneity in at least ",(0,i.jsx)(t.strong,{children:"three aspects of the stack"}),":"]}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"GPU Memory Allocation"}),": How the cache is laid out and allocated on the GPU. vLLM solved this with its Hybrid Memory Allocator (HMA), rebuilt around a unified allocator (see ",(0,i.jsx)(t.a,{href:"https://pytorch.org/blog/hybrid-models-as-first-class-citizens-in-vllm/",children:"Hybrid Models as First-Class Citizens in vLLM"}),")."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"KV Offloading"}),": Extending the KV cache to CPU and storage. Without HMA awareness, an offloading connector turns the HMA off and therefore discards the GPU memory improvements or potential data movement savings."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"KV-Aware Routing"}),": Sending each request to the right model-server replica. Ignoring hybrid memory structure may erroneously list nodes as having or not having the required KV data based on information stemming from just part of the layers."]}),"\n"]}),"\n",(0,i.jsxs)(t.p,{children:["vLLM's HMA solved hybrid GPU memory allocation when handling a single vLLM instance. This post shows how llm-d extends that to ",(0,i.jsx)(t.strong,{children:"tiered KV cache management"})," - including KV offloading to CPU and storage, and KV-aware request routing - significantly improving throughput and latency at scale for hybrid models."]}),"\n",(0,i.jsx)(t.h2,{id:"kv-cache-offloading-for-hybrid-models",children:"KV Cache Offloading for Hybrid Models"}),"\n",(0,i.jsxs)(t.p,{children:["In full-attention layers, the KV cache grows linearly with sequence length, and the workloads people actually run now (agentic loops, multi-turn conversations, long reasoning traces) push context lengths into the hundreds of thousands of tokens. At those sizes, the KV cache is one of the largest consumers of GPU memory. Hybrid models complicate this: sliding-window layers keep only a fixed-size window of KV state, while Mamba/SSM-style and linear-attention layers keep recurrent or fixed-size state rather than a standard per-token KV stream. Each layer type has a different memory footprint and different offloading behavior. KV offloading extends the cache by spilling to CPU DRAM and even storage, keeping more KV data available for ",(0,i.jsx)(t.strong,{children:"reuse across requests"})," - but doing so correctly for hybrid models requires offloading logic aware of these per-layer differences. Our KV offloading path builds on the ",(0,i.jsx)(t.a,{href:"https://blog.vllm.ai/2026/01/08/kv-offloading-connector.html",children:"vLLM native offloading connector"})," and ",(0,i.jsx)(t.a,{href:"/blog/native-kv-cache-offloading-to-any-file-system-with-llm-d",children:"llm-d storage offloading"}),"."]}),"\n",(0,i.jsx)(t.h3,{id:"handling-kv-data-for-hybrid-models",children:"Handling KV Data for Hybrid Models"}),"\n",(0,i.jsxs)(t.p,{children:["Hybrid models interleave different attention types across layers, and each type stores state differently. Take, for example, gpt-oss-120b, which we use throughout this blog as a concrete example, though the connector handles any hybrid model. This model interleaves Full Attention layers (FA) and Sliding Window layers (SWA). Its full-attention layers cache every token, so a 128K-token request holds all 128K tokens of KV in these layers, while its sliding-window layers keep only the last 128 tokens, no matter how long the request runs. Two layer types in one model, with cache footprints that can differ by ",(0,i.jsx)(t.strong,{children:"orders of magnitude"}),"."]}),"\n",(0,i.jsxs)(t.p,{children:["Frontier models keep diverging from uniform full attention models. Mamba and linear-attention layers (Jamba, Qwen3.5) hold a single fixed-size state instead of per-token KV. In such models, rather than keeping a KV stream, checkpoints of intermediate states are maintained and offloaded. New models like Google's Gemma 4 interleave two types of attention, local sliding-window and full global. ",(0,i.jsx)(t.a,{href:"https://vllm.ai/blog/2026-04-24-deepseek-v4",children:"DeepSeek V4"})," goes furthest, mixing compressed attention at two ratios with a short sliding window inside a single model built for million-token context, a five-way cache stack that vLLM folds into a handful of shared page-size buckets just to serve it."]}),"\n",(0,i.jsxs)(t.p,{children:["With the Hybrid Memory Allocator (",(0,i.jsx)(t.strong,{children:"HMA"}),') enabled, vLLM splits the cache into groups \u2013 each group has a uniform attention type and is managed separately. KV data for "old tokens" in a sliding-window group may be evicted, whereas in a full-sequence group these have to be maintained for the entire prompt. For gpt-oss-120b HMA creates two groups: full-attention and sliding-window, shown in Figure 1. With the HMA disabled, these groups collapse into a single full-attention buffer requiring keeping the full attention in memory for all layers. While the model still saves on compute (since SWA layers only compute on a fixed-size window), the memory saving is thrown away.']}),"\n",(0,i.jsxs)("div",{style:{textAlign:"center",margin:"20px 0"},children:[(0,i.jsx)("img",{src:"/img/blogs/hybrid-models/hma-blog-image1.webp",alt:"Per-group offloading",style:{width:"85%",height:"auto"}}),(0,i.jsx)("p",{style:{fontSize:"0.9em",marginTop:"8px"},children:(0,i.jsx)("em",{children:"Figure 1. Per-group offloading: full-attention keeps every block, sliding-window keeps only its window."})})]}),"\n",(0,i.jsx)(t.h3,{id:"handling-hybrid-kv-by-an-offloading-connector",children:"Handling Hybrid KV by an Offloading Connector"}),"\n",(0,i.jsx)(t.p,{children:"Prior to our changes, an offloading connector built for the uniform world handles a hybrid cache in one of two bad ways: Either forgo offloading altogether or forgo the use of HMA. The second is not a failure but a silent slowdown: vLLM falls back to managing the cache as uniform attention blocks, so offloading still succeeds, but the GPU memory savings are lost, and every KV load ends up moving more data than it should."}),"\n",(0,i.jsx)(t.p,{children:"Making the connector genuinely HMA-aware came down to the following changes:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Per-group tensor subsets."})," vLLM makes the connector aware of which tensors belong to which group and their layer type. Lookups of blocks in the connector are also group aware."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Per-group offloads."})," Rather than offloading a single KV block for a chunk of tokens, each group of layers offloads its separate KV data. In storage, this amounts to a separate file per group. For example, in gpt-oss this means two files per chunk instead of one, which the I/O pool can move in parallel."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Partial transfers."})," Some groups only require partial loading of KV data. Sliding-window layers need only the KV of the last tokens in a prompt, so the connector transfers only the in-window blocks. In the case of storage, this often starts from an offset partway into a file rather than the beginning of the file."]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"We built these changes into the vLLM native offloading connector and the llm-d FS connector, handling both the CPU and storage tiers. This allows vLLM to use HMA along with the connector and, as shown below, leads to significant performance improvements."}),"\n",(0,i.jsx)(t.h2,{id:"performance-benefits-nearly-double-the-load-speed",children:"Performance Benefits: Nearly Double the Load Speed"}),"\n",(0,i.jsx)(t.p,{children:'When a request prefix already lives in the offload tier, how fast can we pull it back? We ran a small microbenchmark: run ten distinct 128K-token prompts concurrently. On an initial "cold" pass their KV is written to the offload tier. Then we repeat this on a "hot" pass (with GPU cache disabled) in which the KV data is read back from the offload tier. We measure how long the hot batch takes to complete its KV loads and decode one token for all ten requests (similar to TTFT, but for the whole batch).'}),"\n",(0,i.jsxs)("div",{style:{textAlign:"center",margin:"20px 0"},children:[(0,i.jsx)("img",{src:"/img/blogs/hybrid-models/hma-blog-image2.webp",alt:"Batch KV load latency across tiers",style:{width:"85%",height:"auto"}}),(0,i.jsx)("p",{style:{fontSize:"0.9em",marginTop:"8px"},children:(0,i.jsx)("em",{children:"Figure 2. Batch KV load latency across CPU and storage tiers with HMA and without it. Models are gpt-oss-20b (TP=2) and gpt-oss-120b (TP=4) on NVIDIA H100 GPUs, with IBM Storage Scale as the storage backend. Block size is 16 tokens for the CPU tier and 256 tokens for the storage tier."})})]}),"\n",(0,i.jsxs)(t.p,{children:["The results (in Figure 2) show that HMA-aware reads are ",(0,i.jsx)(t.strong,{children:"1.8x to 1.9x faster"})," on both tiers and both model sizes. The source of these benefits is in the sliding window layers that only need to load the last 128 tokens worth of KV cache instead of the full attention for the entire 128K tokens. On the offload side (after initial prefill) we did not see this benefit, nor any penalty, as we still chose to offload all the KV data. This direction is done asynchronously and thus is less critical."]}),"\n",(0,i.jsx)(t.h2,{id:"scaling-benefits-of-hma-aware-offloading",children:"Scaling Benefits of HMA-Aware Offloading"}),"\n",(0,i.jsxs)(t.p,{children:["HMA pays off irrespective of offloading, because sizing each group to its real need frees a lot of HBM. For example, for a gpt-oss-120b model, vLLM predicts an increase of ",(0,i.jsx)(t.strong,{children:"1.77x in KV cache capacity"})," when turning the HMA configuration flag on (as seen in vLLM's log messages). This is again due to the smaller KV footprint of the sliding-window layers. When testing this with offload tiers underneath, this effect compounds: the GPU can serve more requests, and similarly, the CPU tier can serve more by evicting more non-critical KV data from the sliding-window layers."]}),"\n",(0,i.jsxs)(t.p,{children:["To show the scalability of using offloading, we follow the scalability test from our previous post, ",(0,i.jsx)(t.a,{href:"/blog/native-kv-cache-offloading-to-any-file-system-with-llm-d",children:"Native KV Cache Offloading to Any Filesystem with llm-d"}),". This test sweeps a growing number of users each sending its own (previously seen) prompt of 16K-token with single-token decode. The test runs at maximum query-per-second rate of 80 and max-concurrency of 80 and measures throughput in tokens per second. As the number of users grows, each configuration eventually saturates its memory capacity and drops to prefill level throughput."]}),"\n",(0,i.jsxs)("div",{style:{textAlign:"center",margin:"20px 0"},children:[(0,i.jsx)("img",{src:"/img/blogs/hybrid-models/hma-blog-image3.webp",alt:"User scalability test across tiers",style:{width:"85%",height:"auto"}}),(0,i.jsx)("p",{style:{fontSize:"0.9em",marginTop:"8px"},children:(0,i.jsx)("em",{children:"Figure 3. User scalability test across tiers with gpt-oss-120b (TP=4) on NVIDIA H100 GPUs and IBM Storage Scale as the storage backend, with HMA and without it."})})]}),"\n",(0,i.jsx)(t.p,{children:"HMA-awareness produces two positive effects in this experiment, shown in Figure 3. First, it shifts each saturation cliff to the right: the GPU holds more users with HMA before it saturates, and the CPU tier does the same once it takes over. The storage capacity is large enough that we do not see a collapse to prefill-level throughput in the tested range. Second, it raises the sustained throughput of the slower tiers: with storage added, the GPU + CPU + storage stack settles onto a much higher plateau than without HMA, and manages to sustain this high throughput to the largest user counts tested."}),"\n",(0,i.jsx)(t.h2,{id:"kv-aware-request-routing",children:"KV-Aware Request Routing"}),"\n",(0,i.jsxs)(t.p,{children:["Everything so far ran on a single vLLM instance: the read speedup, the capacity, the throughput under load. Scaling past one instance is where it gets harder, especially without shared storage, because a bigger effective cache per GPU and CPU only helps if each request lands on the replica that already holds its prefix. Spread requests blindly across a fleet and the cache hits drop sharply. Routing requests to where their cache lives is what llm-d does, and it was the subject of our earlier post, ",(0,i.jsx)(t.a,{href:"/blog/kvcache-wins-you-can-see",children:"KV-Cache Wins You Can See"}),", where prefix-aware scheduling gave the scheduler a global view of the cluster's caches. We extended that idea across tiers, so the scheduler scores not just each replica's GPU cache, but its CPU offload tier too, and routes accordingly - we call this ",(0,i.jsx)(t.strong,{children:"multi-tier KV management"}),"."]}),"\n",(0,i.jsx)(t.p,{children:"Routing rides on the KV-events vLLM emits to externalize its cache state. We extended those events to cover the CPU tier, and to carry HMA-group information for hybrid models - so the router can see that a prefix's full-attention layers are still resident even after its sliding-window layers have rolled out of the window, rather than treating the whole block as gone. For models that pair full attention with sliding-window layers, like gpt-oss, the scorer already uses this to route on the layers that are actually retained. Models that are purely sliding-window, or that mix several window sizes, are the harder case, and a dedicated scorer to handle them optimally is in progress; the results below come from the existing tier-aware scorer."}),"\n",(0,i.jsx)(t.p,{children:"To exemplify routing with hybrid models we benchmarked a fleet of 16 gpt-oss-120b servers at three levels of management, sweeping 5 to 40 QPS (workload: 250 prefix groups, 5 prompts per group, 16K-token system prompt, 256-token question, 256-token output):"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"GPU-only KV management"}),": the scheduler scores only the GPU cache (our baseline)."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"GPU KV management + CPU offloading"}),": a CPU tier absorbs the overflow, but routing still scores only the GPU."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"GPU+CPU KV management"}),": the scheduler scores both the GPU and the CPU tier, so each request routes to wherever its prefix actually lives."]}),"\n"]}),"\n",(0,i.jsxs)("div",{style:{textAlign:"center",margin:"20px 0"},children:[(0,i.jsx)("img",{src:"/img/blogs/hybrid-models/hma-blog-image4.webp",alt:"KV cache management across a 16-server fleet",style:{width:"85%",height:"auto"}}),(0,i.jsx)("p",{style:{fontSize:"0.9em",marginTop:"8px"},children:(0,i.jsx)("em",{children:"Figure 4. KV cache management across a 16-server gpt-oss-120b fleet (TP=1, one NVIDIA H100 per server): TTFT and throughput vs request rate."})})]}),"\n",(0,i.jsxs)(t.p,{children:["The payoff shows up under load. Past about 20 QPS the GPU-only baseline saturates and its TTFT climbs into the tens of seconds as requests queue. Adding a CPU offload tier helps: at 40 QPS it lifts throughput about ",(0,i.jsx)(t.strong,{children:"75%"})," over the baseline while holding TTFT low. But the real win comes from managing both tiers together. With GPU+CPU KV management, ",(0,i.jsx)(t.strong,{children:"throughput rises roughly 115% over the baseline at 40 QPS, and TTFT stays essentially flat across the whole sweep"}),"."]}),"\n",(0,i.jsxs)(t.p,{children:["That gap is llm-d's value: ",(0,i.jsx)(t.strong,{children:"the offload tier only reaches its full potential when the scheduler knows what it holds and routes to it"}),". Capacity is a property of an instance; throughput is a property of placement."]}),"\n",(0,i.jsxs)(t.p,{children:["The full setup, the per-QPS results, and step-by-step instructions to run it yourself are in the ",(0,i.jsx)(t.a,{href:"https://github.com/llm-d/llm-d/tree/main/guides/tiered-prefix-cache#gpt-oss-120b-benchmarking-results",children:"llm-d tiered prefix cache guide"}),"."]}),"\n",(0,i.jsx)(t.h2,{id:"whats-next",children:"What's Next"}),"\n",(0,i.jsxs)(t.p,{children:["The experiments in this post used the standalone llm-d FS connector. The same HMA-aware offloading path has also been implemented in the new multi-tier connector upstreamed to vLLM, which is intended to replace the standalone connector going forward. See the ",(0,i.jsx)(t.a,{href:"https://docs.vllm.ai/en/latest/features/kv_offloading_usage/",children:"vLLM KV offloading guide"}),". The multi-tier design is more than just packaging. With CPU and storage managed as tiers of one connector, CPU serves as a hub for hot data and a staging area for slower storage."]}),"\n",(0,i.jsxs)(t.p,{children:["The HMA results here rely on canonical KV-cache allocation for HMA models in vLLM (",(0,i.jsx)(t.a,{href:"https://github.com/vllm-project/vllm/pull/37885",children:"PR #37885"}),"), which has not yet merged, so reproducing them requires a build from that branch."]}),"\n",(0,i.jsx)(t.p,{children:"HMA itself is not a solved problem. Every new model brings new attention layers, and each one is another cache group the connector has to handle correctly. As context lengths and model counts keep growing, getting that offloading right is no longer a nice-to-have; it is what keeps serving affordable."}),"\n",(0,i.jsx)(t.h2,{id:"get-involved-with-llm-d",children:"Get Involved with llm-d"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:["Explore the llm-d Community Quickstart Guide \u2192 ",(0,i.jsx)(t.a,{href:"https://github.com/llm-d/llm-d/blob/main/README.md",children:"Start here"})]}),"\n",(0,i.jsxs)(t.li,{children:["Join our Slack \u2192 ",(0,i.jsx)(t.a,{href:"https://inviter.co/llm-d-slack",children:"Get your invite"})," and connect with maintainers and contributors"]}),"\n",(0,i.jsxs)(t.li,{children:["Explore the code \u2192 ",(0,i.jsx)(t.a,{href:"https://github.com/llm-d",children:"Browse our GitHub organization"})]}),"\n",(0,i.jsxs)(t.li,{children:["Attend meetings \u2192 All meetings are open! Add our ",(0,i.jsx)(t.a,{href:"https://red.ht/llm-d-public-calendar",children:"public calendar"})]}),"\n"]})]})}function c(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var o=n(96540);const i={},a=o.createContext(i);function s(e){const t=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),o.createElement(a.Provider,{value:t},e.children)}},27571(e){e.exports=JSON.parse('{"permalink":"/llm-d.github.io/blog/serving-hybrid-models-at-scale-in-llm-d","editUrl":"https://github.com/llm-d/llm-d/edit/main/website/blog/2026-06-13_serving-hybrid-models-at-scale-in-llm-d.mdx","source":"@site/blog/2026-06-13_serving-hybrid-models-at-scale-in-llm-d.mdx","title":"Serving Hybrid Models at Scale in llm-d","description":"llm-d extends vLLM\'s Hybrid Memory Allocator across KV offloading to CPU and storage and KV-aware routing, making the offload connector HMA-aware - for 1.8\u20131.9x faster KV loads and about 115% higher throughput at high request rates with stable latency.","date":"2026-06-13T09:00:00.000Z","tags":[{"inline":false,"label":"blog posts","permalink":"/llm-d.github.io/blog/tags/blog","description":"everyday blog posts"},{"inline":false,"label":"KV Cache","permalink":"/llm-d.github.io/blog/tags/kv-cache","description":"KV caching for LLM inference"},{"inline":false,"label":"Storage","permalink":"/llm-d.github.io/blog/tags/storage","description":"Storage related content"},{"inline":false,"label":"HMA","permalink":"/llm-d.github.io/blog/tags/hma","description":"Hybrid Memory Allocator and serving hybrid models"},{"inline":false,"label":"Inference","permalink":"/llm-d.github.io/blog/tags/inference","description":"LLM inference serving and optimization"},{"inline":false,"label":"Scheduling","permalink":"/llm-d.github.io/blog/tags/scheduling","description":"Request scheduling and load balancing for LLM inference"}],"readingTime":13.42,"hasTruncateMarker":true,"authors":[{"name":"Kfir Toledo","title":"Research Staff Member, IBM","socials":{"linkedin":"https://www.linkedin.com/in/kfir-toledo-394a8811a/"},"imageURL":"/llm-d.github.io/img/blogs/kfirtoledo.webp","key":"kfirtoledo","page":null},{"name":"Or Ozeri","title":"Research Staff Member, IBM","socials":{"linkedin":"https://www.linkedin.com/in/or-ozeri-a942859a/"},"imageURL":"/llm-d.github.io/img/blogs/orozeri.webp","key":"orozeri","page":null},{"name":"Danny Harnik","title":"Senior Technical Staff Member, IBM","socials":{"linkedin":"https://www.linkedin.com/in/danny-harnik-19a95436/"},"imageURL":"/llm-d.github.io/img/blogs/dannyharnik.webp","key":"dannyharnik","page":null},{"name":"Itay Etelis","title":"Research Staff Member, IBM","socials":{"linkedin":"https://www.linkedin.com/in/itay-etelis-1692ba157/"},"imageURL":"/llm-d.github.io/img/blogs/itayetelis.webp","key":"itayetelis","page":null},{"name":"Rachel Brill","title":"Senior Technical Staff Member, IBM","socials":{"linkedin":"https://www.linkedin.com/in/rachel-tzoref-brill-6645a11/"},"imageURL":"/llm-d.github.io/img/blogs/rachelbrill.webp","key":"rachelbrill","page":null},{"name":"Maroon Ayoub","title":"Senior Principal Machine Learning Engineer, Red Hat","socials":{"linkedin":"https://www.linkedin.com/in/v-maroon/"},"imageURL":"/llm-d.github.io/img/blogs/maroonayoub.webp","key":"maroonayoub-redhat","page":null}],"frontMatter":{"title":"Serving Hybrid Models at Scale in llm-d","description":"llm-d extends vLLM\'s Hybrid Memory Allocator across KV offloading to CPU and storage and KV-aware routing, making the offload connector HMA-aware - for 1.8\u20131.9x faster KV loads and about 115% higher throughput at high request rates with stable latency.","slug":"serving-hybrid-models-at-scale-in-llm-d","date":"2026-06-13T09:00","authors":["kfirtoledo","orozeri","dannyharnik","itayetelis","rachelbrill","maroonayoub-redhat"],"tags":["blog","kv-cache","storage","hma","inference","scheduling"]},"unlisted":false,"prevItem":{"title":"Networking for Distributed Inference in llm-d","permalink":"/llm-d.github.io/blog/networking-for-distributed-inference-llm-d"},"nextItem":{"title":"Heterogeneous inference serving across three GPU vendors with llm-d","permalink":"/llm-d.github.io/blog/heterogeneous-inference-3-vendor-sovereign-cluster"}}')}}]);